-- PsyLab V64 — La Blouse : challenge avancé « Compatible n’est pas discriminant »
-- À exécuter après V62. V64 enrichit le template courant (8 phases) et conserve les autres semaines V62.

update public.challenge_templates
set content=$json${"fr":{"title":"Compatible n’est pas discriminant","subtitle":"Un symptôme partagé ne tranche pas le différentiel.","intro":"Plusieurs éléments évoquent une bipolarité. Le défi consiste à déterminer lesquels modifient réellement la probabilité diagnostique et lesquels ne sont que des faux amis.","central_trap":"Compatible n’est pas discriminant","central_trap_explanation":"Le dossier accumule volontairement des signes compatibles avec plusieurs diagnostics. La difficulté est de ne pas confondre ressemblance clinique et valeur discriminante.","reflex":"Avant de conclure, cherchez le phénomène, sa temporalité et le changement par rapport au fonctionnement habituel.","hypotheses":["Trouble dépressif majeur récurrent","Trouble bipolaire II","Trouble anxieux avec symptômes dépressifs","Trouble de l’humeur induit par substance ou médicament"],"steps":[{"kind":"rank","short":"Hypothèses","label":"Carte d’hypothèses","question":"À partir de ce premier tableau, comment hiérarchisez-vous les hypothèses ?","instruction":"Mme A., 31 ans, consulte pour un troisième épisode dépressif. Depuis trois semaines, elle décrit une humeur dépressive, une perte d’élan et une fatigue importante. Elle ajoute que son « cerveau ne s’arrête jamais », dort environ quatre heures par nuit, se montre irritable et dit que son humeur peut changer plusieurs fois dans la journée. Elle rapporte aussi quelques achats en ligne impulsifs. Aucun épisode d’activation distinct n’est rapporté spontanément.","hypotheses":["Trouble dépressif majeur récurrent","Trouble bipolaire II","Trouble anxieux avec symptômes dépressifs","Trouble de l’humeur induit par substance ou médicament"],"trap":"Additionner des signes évocateurs de bipolarité sans vérifier s’ils appartiennent à un épisode distinct.","discriminant":"À ce stade, aucune donnée ne caractérise encore une hypomanie ; l’incertitude doit être conservée.","debrief":"La plainte contient plusieurs signaux compatibles avec une activation, mais ils sont encore transversaux et non spécifiques. Le raisonnement le plus robuste garde le trouble dépressif en tête tout en maintenant la bipolarité dans le différentiel."},{"kind":"multi","short":"Exploration","label":"Budget d’exploration","question":"Vous ne pouvez approfondir que trois éléments avant de poursuivre. Lesquels choisissez-vous ?","instruction":"Chaque choix consomme une partie de votre budget d’exploration. Cherchez les informations capables de modifier l’arbre diagnostique, pas celles qui sont seulement intéressantes.","required":3,"choices":["Phénoménologie du sommeil : désir de dormir davantage, fatigue, récupération","Recherche ciblée de périodes antérieures nettement délimitées d’augmentation d’énergie et d’activité","Changements observables du fonctionnement rapportés par l’entourage lors d’éventuelles périodes d’activation","Antécédents familiaux de trouble bipolaire","Score à un questionnaire de dépistage de bipolarité","Tempérament depuis l’adolescence","Variation pondérale pendant l’épisode actuel","Préférence pour travailler la nuit","Nombre de consultations psychologiques antérieures","Caractéristiques détaillées de son poste de travail"],"trap":"Choisir des marqueurs de risque ou des outils de dépistage avant d’avoir caractérisé le phénomène clinique et sa temporalité.","discriminant":"Sommeil qualitatif, épisodicité et changement observable par rapport au baseline.","debrief":"Les trois choix les plus rentables sont ceux qui permettent de distinguer une activation syndromique d’une insomnie anxieuse ou d’une variabilité émotionnelle non épisodique."},{"kind":"single","short":"Données","label":"Données contradictoires","question":"Comment ces nouvelles informations modifient-elles votre hypothèse de bipolarité ?","evidence":"Elle souhaiterait dormir davantage mais reste éveillée par des ruminations anxieuses ; elle est épuisée le matin et récupère le week-end. Les pensées « qui défilent » sont décrites comme une succession de préoccupations répétitives. Les variations d’humeur surviennent en quelques heures, généralement après des interactions stressantes. Elle ne décrit pas d’augmentation parallèle de l’énergie ni de l’activité orientée vers un but.","choices":["Elles rendent un trouble bipolaire II beaucoup plus probable","Elles diminuent la probabilité d’un trouble bipolaire II sans l’exclure encore","Elles prouvent un trouble anxieux et ferment le différentiel","Elles n’ont aucune valeur diagnostique"],"trap":"Assimiler automatiquement sommeil court à diminution du besoin de sommeil et pensée rapide à fuite des idées.","discriminant":"Le besoin de sommeil persiste, la fatigue est présente et les pensées ont la forme de ruminations ; l’activation syndromique n’est pas démontrée.","debrief":"La qualité phénoménologique des symptômes compte davantage que leur étiquette superficielle. Ces données diminuent la probabilité d’une hypomanie, mais la reconstruction longitudinale reste nécessaire."},{"kind":"timeline","short":"Chronologie","label":"Reconstruction temporelle","question":"Remettez les événements dans l’ordre chronologique.","instruction":"Le diagnostic dépend ici davantage de la structure temporelle que du nombre brut de symptômes.","events":[{"title":"Consultation actuelle","detail":"Octobre 2026"},{"title":"Deuxième épisode dépressif, puis retour au fonctionnement habituel","detail":"2023"},{"title":"Premier épisode dépressif caractérisé, suivi d’une rémission","detail":"2021"},{"title":"Trois jours de travail intensif avant un examen ; sommeil réduit avec fatigue et récupération ensuite","detail":"Janvier 2026"},{"title":"Début de l’épisode dépressif actuel","detail":"Septembre 2026"}],"trap":"Transformer une courte période de suractivité contextuelle en épisode hypomaniaque parce qu’elle ressemble partiellement à de l’activation.","discriminant":"Les épisodes dépressifs sont séparés par un retour au baseline ; aucune période d’activation autonome suffisamment caractérisée n’émerge de la chronologie.","debrief":"La chronologie permet de distinguer une maladie épisodique d’événements contextuels qui n’atteignent pas un seuil syndromique."},{"kind":"single","short":"Révision","label":"Révision d’hypothèse","question":"Après cette reconstruction et l’information de la sœur, quelle révision est la plus défendable ?","evidence":"La sœur confirme des épisodes dépressifs séparés par des périodes de fonctionnement habituel. Elle n’a jamais observé de période distincte de plusieurs jours où Mme A. aurait été à la fois nettement plus énergique, plus active et différente d’elle-même. Les rares périodes de sommeil court correspondaient à des échéances ; Mme A. se plaignait alors de fatigue et cherchait à récupérer ensuite.","choices":["Maintenir le trouble bipolaire II comme hypothèse principale","Placer le trouble dépressif récurrent en tête tout en gardant le trouble bipolaire II comme différentiel surveillé","Écarter définitivement toute bipolarité future","Conclure à un trouble induit par une substance"],"leader_map":{"0":1,"1":0,"2":0,"3":3},"trap":"S’accrocher à l’hypothèse initiale malgré l’accumulation de données qui en réduisent la probabilité.","discriminant":"Absence, après enquête ciblée et collatérale, d’un épisode distinct d’augmentation d’énergie/activité avec réduction du besoin de sommeil.","debrief":"Réviser une hypothèse n’est pas une erreur : c’est une compétence. Ici, le trouble bipolaire II reste un différentiel longitudinal, mais il n’est plus l’hypothèse principale."},{"kind":"single","short":"Contrefactuel","label":"Ce qui vous ferait changer d’avis","question":"Quelle information nouvelle ferait le plus fortement remonter l’hypothèse de trouble bipolaire II ?","choices":["Un épisode distinct d’au moins plusieurs jours avec réduction du besoin de sommeil, augmentation nette d’énergie et d’activité, changement observable par les proches, sans retentissement maniaque majeur","Un antécédent familial isolé de trouble bipolaire","Un questionnaire de dépistage positif","Une amélioration partielle sous antidépresseur"],"trap":"Donner à un facteur de risque ou à un dépistage la même valeur qu’à un épisode clinique caractérisé.","discriminant":"Un épisode hypomaniaque suffisamment caractérisé modifierait directement l’architecture diagnostique.","debrief":"La question contrefactuelle teste si vous savez quelles données ont réellement le pouvoir de faire basculer votre diagnostic."},{"kind":"single","short":"Discriminant","label":"Élément discriminant","question":"Quel élément du dossier doit peser le plus contre l’interprétation « hypomanie actuelle » ?","choices":["Les phénomènes d’apparente activation surviennent au sein d’un état dépressif/anxieux, sans période distincte d’augmentation d’énergie et d’activité ni réduction du besoin de sommeil","La patiente a 31 ans","Elle a effectué quelques achats en ligne impulsifs","Elle a des antécédents de dépression"],"trap":"Privilégier un symptôme spectaculaire mais peu spécifique plutôt que la structure syndromique et temporelle.","discriminant":"Absence d’un épisode distinct et absence de diminution du besoin de sommeil malgré le sommeil raccourci.","debrief":"Le signe le plus utile n’est pas celui qui attire le plus l’attention ; c’est celui qui sépare réellement les hypothèses concurrentes."},{"kind":"final","short":"Signature","label":"Synthèse et signature","question":"Signez le dossier avec une synthèse proportionnée aux données disponibles.","diagnosis_choices":["Trouble dépressif majeur récurrent","Trouble bipolaire II","Trouble anxieux généralisé","Trouble de l’humeur induit par substance ou médicament"],"differential_choices":["Trouble bipolaire II à poursuivre longitudinalement","Trouble dépressif majeur récurrent","Trouble de l’adaptation","Aucun différentiel utile"],"argument_choices":["La présence de plusieurs symptômes compatibles avec une activation","L’absence de psychose","L’absence d’épisode hypomaniaque distinct après reconstruction longitudinale, avec sommeil court vécu comme une insomnie fatigante plutôt qu’une diminution du besoin de sommeil","Un questionnaire de dépistage non réalisé"],"trap":"Signer un diagnostic sur la somme de symptômes compatibles au lieu de la structure du syndrome.","discriminant":"Pas d’épisode hypomaniaque suffisamment caractérisé ; les faux amis sont expliqués par l’épisode dépressif et l’anxiété associée.","debrief":"La synthèse la plus rigoureuse retient un trouble dépressif récurrent tout en gardant la bipolarité comme différentiel longitudinal à réévaluer si de nouvelles données apparaissent."}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Jansson & Nordgaard — The Psychiatric Interview","Shorter Oxford Textbook of Psychiatry — Bipolar disorder","Lalonde — Psychiatrie clinique : approche bio-psycho-sociale"]},"en":{"title":"Compatible is not discriminating","subtitle":"A shared symptom does not settle the differential.","intro":"Several findings suggest bipolarity. The challenge is to determine which ones truly change diagnostic probability and which are look-alikes.","central_trap":"Compatible is not discriminating","central_trap_explanation":"The case deliberately accumulates features that fit more than one diagnosis. The challenge is not to confuse resemblance with discriminating value.","reflex":"Before concluding, identify the phenomenon, its temporal structure and the change from baseline.","hypotheses":["Recurrent major depressive disorder","Bipolar II disorder","Anxiety disorder with depressive symptoms","Substance/medication-induced mood disorder"],"steps":[{"kind":"rank","short":"Hypotheses","label":"Hypothesis map","question":"From this initial presentation, how do you rank the competing hypotheses?","instruction":"Ms A., 31, presents with a third depressive episode. For three weeks she has had depressed mood, loss of drive and marked fatigue. She says her “brain never stops,” sleeps about four hours a night, is irritable and reports several mood shifts within the same day. She also mentions occasional impulsive online purchases. No distinct past activation episode is spontaneously reported.","hypotheses":["Recurrent major depressive disorder","Bipolar II disorder","Anxiety disorder with depressive symptoms","Substance/medication-induced mood disorder"],"trap":"Adding together bipolar-compatible signs without checking whether they form a distinct episode.","discriminant":"At this point no evidence yet establishes hypomania; uncertainty must be preserved.","debrief":"Several findings are compatible with activation, but they remain cross-sectional and nonspecific. The most robust reasoning keeps recurrent depression first while retaining bipolarity in the differential."},{"kind":"multi","short":"Exploration","label":"Exploration budget","question":"You can investigate only three areas before proceeding. Which do you choose?","instruction":"Each choice uses part of your exploration budget. Seek information that can change the diagnostic tree, not information that is merely interesting.","required":3,"choices":["Sleep phenomenology: desire for more sleep, fatigue, recovery","Targeted search for distinct past periods of increased energy and activity","Observable changes from baseline reported by relatives during possible activation periods","Family history of bipolar disorder","A positive bipolar screening questionnaire score","Temperament since adolescence","Weight change during the current episode","Preference for night work","Number of previous psychotherapy consultations","Detailed characteristics of her job"],"trap":"Prioritizing risk markers or screening tools before characterizing the clinical phenomenon and its timing.","discriminant":"Qualitative sleep features, episodicity and observable change from baseline.","debrief":"The most useful choices are the ones that distinguish syndromic activation from anxious insomnia or non-episodic emotional variability."},{"kind":"single","short":"Evidence","label":"Contradictory evidence","question":"How should these new findings change the probability of bipolar II disorder?","evidence":"She wishes she could sleep more but stays awake because of anxious rumination; she is exhausted in the morning and catches up on sleep on weekends. The “racing thoughts” are repetitive worries. Her mood shifts occur within hours, usually after stressful interactions. She does not report a parallel increase in energy or goal-directed activity.","choices":["They make bipolar II much more likely","They lower the probability of bipolar II without excluding it yet","They prove an anxiety disorder and close the differential","They have no diagnostic value"],"trap":"Equating short sleep with reduced need for sleep, and fast thoughts with flight of ideas.","discriminant":"The need for sleep persists, fatigue is present, and the thoughts are ruminative rather than a clear activation syndrome.","debrief":"Phenomenological quality matters more than the superficial label. These data lower the likelihood of hypomania, but longitudinal reconstruction is still required."},{"kind":"timeline","short":"Timeline","label":"Timeline reconstruction","question":"Put the events in chronological order.","instruction":"Here the temporal structure matters more than the raw number of symptoms.","events":[{"title":"Current consultation","detail":"October 2026"},{"title":"Second depressive episode, followed by return to usual functioning","detail":"2023"},{"title":"First major depressive episode, followed by remission","detail":"2021"},{"title":"Three days of intensive work before an exam; reduced sleep with fatigue and later recovery","detail":"January 2026"},{"title":"Onset of the current depressive episode","detail":"September 2026"}],"trap":"Turning a short, context-driven period of overwork into hypomania because it partially resembles activation.","discriminant":"Depressive episodes are separated by return to baseline; no autonomous, sufficiently characterized activation episode emerges.","debrief":"The timeline separates episodic illness from contextual changes that do not cross a syndromic threshold."},{"kind":"single","short":"Revision","label":"Hypothesis revision","question":"After reconstructing the course and hearing collateral information, what revision is most defensible?","evidence":"Her sister confirms depressive episodes separated by usual functioning. She has never observed a distinct period of several days during which Ms A. was clearly more energetic, more active and unlike herself. The few periods of short sleep occurred around deadlines; Ms A. complained of fatigue and tried to recover afterward.","choices":["Keep bipolar II as the leading diagnosis","Move recurrent major depression to the top while keeping bipolar II as a longitudinal differential","Permanently exclude any future possibility of bipolarity","Diagnose a substance-induced mood disorder"],"leader_map":{"0":1,"1":0,"2":0,"3":3},"trap":"Clinging to an initial hypothesis despite accumulating evidence that lowers its probability.","discriminant":"No distinct activation episode with increased energy/activity and reduced need for sleep is found after targeted and collateral inquiry.","debrief":"Revising a hypothesis is a clinical skill, not a failure. Bipolar II remains a longitudinal differential, but it is no longer the leading explanation."},{"kind":"single","short":"Counterfactual","label":"What would change your mind?","question":"Which new finding would most strongly increase the probability of bipolar II disorder?","choices":["A distinct period lasting several days with reduced need for sleep, clear increase in energy/activity and observable change from baseline, without manic-level impairment","An isolated family history of bipolar disorder","A positive bipolar screening questionnaire","Partial improvement with an antidepressant"],"trap":"Giving a risk factor or screening result the same weight as a characterized clinical episode.","discriminant":"A sufficiently characterized hypomanic episode would directly alter the diagnostic architecture.","debrief":"The counterfactual question tests whether you know which information has enough weight to change the diagnosis."},{"kind":"single","short":"Discriminant","label":"Discriminating clue","question":"Which finding should weigh most strongly against interpreting the current symptoms as hypomania?","choices":["The apparent activation occurs inside a depressive/anxious state, without a distinct period of increased energy/activity or reduced need for sleep","The patient is 31","She made a few impulsive online purchases","She has previous depressive episodes"],"trap":"Choosing a striking but nonspecific symptom over syndromic and temporal structure.","discriminant":"No distinct activation episode and no reduced need for sleep despite short sleep duration.","debrief":"The most useful clue is not the most dramatic one; it is the one that actually separates competing hypotheses."},{"kind":"final","short":"Signature","label":"Clinical synthesis","question":"Sign the case with a synthesis proportionate to the available evidence.","diagnosis_choices":["Recurrent major depressive disorder","Bipolar II disorder","Generalized anxiety disorder","Substance/medication-induced mood disorder"],"differential_choices":["Bipolar II disorder to continue monitoring longitudinally","Recurrent major depressive disorder","Adjustment disorder","No useful differential"],"argument_choices":["The presence of several symptoms compatible with activation","The absence of psychosis","No distinct hypomanic episode after longitudinal reconstruction, with short sleep experienced as fatiguing insomnia rather than reduced need for sleep","A screening questionnaire was not performed"],"trap":"Signing a diagnosis from the sum of compatible symptoms instead of the structure of the syndrome.","discriminant":"No sufficiently characterized hypomanic episode; the apparent activation signs are better explained within depression and associated anxiety.","debrief":"The most rigorous synthesis retains recurrent major depression while keeping bipolarity as a longitudinal differential to revisit if new evidence emerges."}],"references":["DSM-5-TR — Bipolar and Related Disorders","Jansson & Nordgaard — The Psychiatric Interview","Shorter Oxford Textbook of Psychiatry — Bipolar disorder","Lalonde — Clinical Psychiatry"]}}$json$::jsonb,
    answer_key=$json${"steps":[{"kind":"rank","ranking":[0,1,2,3],"certainty_target":50},{"kind":"multi","correct":[0,1,2],"certainty_target":75},{"kind":"single","correct":1,"certainty_target":75},{"kind":"timeline","order":[2,1,3,4,0]},{"kind":"single","correct":1,"certainty_target":85},{"kind":"single","correct":0,"certainty_target":80},{"kind":"single","correct":0},{"kind":"final","diagnosis":0,"differential":0,"argument":2,"certainty_target":85}]}$json$::jsonb,
    max_score=100
where template_id=6 and course_key='bipolar';

-- Conserver le moteur V62 pour les autres templates si ce backup n'existe pas encore.
do $do$
begin
  if to_regprocedure('public.submit_weekly_challenge_v62(text,jsonb)') is null then
    alter function public.submit_weekly_challenge(text,jsonb) rename to submit_weekly_challenge_v62;
  end if;
end
$do$;

create or replace function public.submit_weekly_challenge(p_challenge_key text,p_answers jsonb)
returns table(score integer,accepted boolean,breakdown jsonb)
language plpgsql security definer set search_path=public as $fn$
declare
  v_uid uuid:=auth.uid(); v_start timestamptz:=date_trunc('week',now()); v_expected_key text;
  v_count int; v_offset int; v_template_id int; v_key jsonb; v_existing int; v_existing_breakdown jsonb;
  a jsonb; exp jsonb; i int; conf int; target int; diff int; choice int;
  selected jsonb; correct jsonb; overlap int; ord jsonb; expected_ord jsonb; pos_matches int;
  ranking jsonb; expected_rank jsonb; diag int; differential int; arg int;
  semio int:=0; searchscore int:=0; timeline int:=0; hierarchy int:=0; revision int:=0; argument int:=0; calibration int:=0;
  stages jsonb:='[]'::jsonb; stage int:=0; result jsonb;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select count(*) into v_count from public.challenge_templates where course_key='bipolar';
  if v_count=0 then raise exception 'No challenge template'; end if;
  v_offset:=(extract(week from v_start)::int % v_count);
  v_expected_key:='bipolar-'||to_char(v_start,'IYYY-IW');
  if p_challenge_key<>v_expected_key then raise exception 'Challenge is not current'; end if;
  select ct.template_id,ct.answer_key into v_template_id,v_key from public.challenge_templates ct where ct.course_key='bipolar' order by ct.template_id offset v_offset limit 1;

  if v_template_id<>6 or jsonb_array_length(v_key->'steps')<>8 then
    return query select * from public.submit_weekly_challenge_v62(p_challenge_key,p_answers); return;
  end if;
  if jsonb_typeof(p_answers)<>'array' or jsonb_array_length(p_answers)<>8 then raise exception 'Incomplete challenge'; end if;
  select ca.score,ca.breakdown into v_existing,v_existing_breakdown from public.challenge_attempts ca where ca.user_id=v_uid and ca.challenge_key=p_challenge_key;
  if v_existing is not null then score:=v_existing;accepted:=false;breakdown:=coalesce(v_existing_breakdown,'{}'::jsonb);return next;return; end if;

  for i in 0..7 loop
    exp:=v_key->'steps'->i; a:=p_answers->i; stage:=0; conf:=greatest(0,least(coalesce((a->>'confidence')::int,50),100));
    if i=0 then
      ranking:=coalesce(a->'ranking','[]'::jsonb); expected_rank:=exp->'ranking';
      if jsonb_array_length(ranking)=4 then
        if (ranking->>0)::int=(expected_rank->>0)::int then hierarchy:=hierarchy+7;stage:=stage+7;end if;
        if (ranking->>1)::int=(expected_rank->>1)::int then hierarchy:=hierarchy+3;stage:=stage+3;end if;
      end if;
    elsif i=1 then
      selected:=coalesce(a->'selected','[]'::jsonb); correct:=exp->'correct';
      select count(*) into overlap from jsonb_array_elements_text(selected) s where exists(select 1 from jsonb_array_elements_text(correct) c where c.value=s.value);
      searchscore:=case overlap when 3 then 20 when 2 then 13 when 1 then 7 else 0 end; stage:=stage+searchscore;
    elsif i=2 then
      choice:=coalesce((a->>'choice')::int,-1); if choice=(exp->>'correct')::int then semio:=semio+6;revision:=revision+5;stage:=stage+11;end if;
    elsif i=3 then
      ord:=coalesce(a->'order','[]'::jsonb); expected_ord:=exp->'order'; pos_matches:=0;
      if jsonb_array_length(ord)=5 then for diff in 0..4 loop if (ord->>diff)::int=(expected_ord->>diff)::int then pos_matches:=pos_matches+1; end if; end loop; end if;
      timeline:=least(15,pos_matches*3);stage:=stage+timeline;
    elsif i=4 then
      choice:=coalesce((a->>'choice')::int,-1); if choice=(exp->>'correct')::int then revision:=revision+10;hierarchy:=hierarchy+5;stage:=stage+15;end if;
    elsif i=5 then
      choice:=coalesce((a->>'choice')::int,-1); if choice=(exp->>'correct')::int then semio:=semio+4;argument:=argument+4;stage:=stage+8;end if;
    elsif i=6 then
      choice:=coalesce((a->>'choice')::int,-1); if choice=(exp->>'correct')::int then argument:=argument+4;stage:=stage+4;end if;
    elsif i=7 then
      diag:=coalesce((a->>'diagnosis')::int,-1);differential:=coalesce((a->>'differential')::int,-1);arg:=coalesce((a->>'argument')::int,-1);
      if diag=(exp->>'diagnosis')::int then semio:=semio+3;stage:=stage+3;end if;
      if differential=(exp->>'differential')::int then semio:=semio+2;stage:=stage+2;end if;
      if arg=(exp->>'argument')::int then argument:=argument+2;stage:=stage+2;end if;
    end if;
    if i in (0,1,2,4,7) then
      target:=coalesce((exp->>'certainty_target')::int,75); diff:=abs(conf-target);
      if diff<=10 then calibration:=calibration+2;stage:=stage+2; elsif diff<=25 then calibration:=calibration+1;stage:=stage+1; end if;
    end if;
    stages:=stages||jsonb_build_array(stage);
  end loop;
  semio:=least(semio,15);searchscore:=least(searchscore,20);timeline:=least(timeline,15);hierarchy:=least(hierarchy,15);revision:=least(revision,15);argument:=least(argument,10);calibration:=least(calibration,10);
  score:=semio+searchscore+timeline+hierarchy+revision+argument+calibration;
  result:=jsonb_build_object('dimensions',jsonb_build_object('semiology',semio,'information_search',searchscore,'timeline',timeline,'hierarchy',hierarchy,'revision',revision,'argument',argument,'calibration',calibration),'stages',stages,'template_id',v_template_id,'debrief_locked_until',v_start+interval '7 days');
  insert into public.challenge_attempts(user_id,challenge_key,course_key,score,answers,breakdown) values(v_uid,p_challenge_key,'bipolar',score,p_answers,result);
  accepted:=true;breakdown:=result;return next;
end;$fn$;
revoke all on function public.submit_weekly_challenge(text,jsonb) from public;
grant execute on function public.submit_weekly_challenge(text,jsonb) to authenticated;

-- Le format du défi courant change : réinitialiser uniquement les tentatives de cette semaine.
delete from public.challenge_attempts where course_key='bipolar' and challenge_key='bipolar-'||to_char(date_trunc('week',now()),'IYYY-IW');
